package com.example.onlineshop.catalog.api;
import com.example.onlineshop.catalog.application.*;import com.example.onlineshop.catalog.application.CatalogReadPort.*;import jakarta.servlet.http.HttpServletRequest;import java.math.*;import java.util.*;import java.util.regex.Pattern;import org.springframework.web.bind.annotation.*;
@RestController @RequestMapping("/api/v2/products") final class CatalogV2Controller {
 private static final Set<String> PARAMS=Set.of("page","size","sort","category","attribute","availability","minPrice","maxPrice","currency"),SORTS=Set.of("updated-desc","name-asc","price-asc","price-desc"),AVAIL=Set.of("any","in-stock","out-of-stock");private static final Pattern SLUG=Pattern.compile("[a-z0-9]+(?:-[a-z0-9]+)*");private final CatalogReadPort reads;CatalogV2Controller(CatalogReadPort reads){this.reads=reads;}
 @GetMapping ProductPage browse(HttpServletRequest request,@RequestParam(defaultValue="0") int page,@RequestParam(defaultValue="20") int size,@RequestParam(defaultValue="updated-desc") String sort,@RequestParam(defaultValue="any") String availability,@RequestParam(required=false) List<String> category,@RequestParam(required=false) List<String> attribute,@RequestParam(required=false) String minPrice,@RequestParam(required=false) String maxPrice,@RequestParam(required=false) String currency){var errors=new ArrayList<InvalidCatalogQueryException.Violation>();request.getParameterMap().keySet().stream().filter(x->!PARAMS.contains(x)).forEach(x->errors.add(v(x,"unknown query parameter")));if(page<0)errors.add(v("page","must be at least 0"));if(size<1||size>100)errors.add(v("size","must be between 1 and 100"));try{Math.multiplyExact((long)page,size);}catch(ArithmeticException e){errors.add(v("page","offset is too large"));}if(!SORTS.contains(sort))errors.add(v("sort","unsupported sort"));if(!AVAIL.contains(availability))errors.add(v("availability","unsupported availability"));var cats=category==null?List.<String>of():category;if(cats.size()>50)errors.add(v("category","at most 50 values are allowed"));if(currency!=null&&!currency.matches("[A-Z]{3}"))errors.add(v("currency","must be an uppercase ISO currency"));BigDecimal min=decimal("minPrice",minPrice,errors),max=decimal("maxPrice",maxPrice,errors);if((min!=null||max!=null)&&currency==null)errors.add(v("currency","is required with a price bound"));if(min!=null&&max!=null&&min.compareTo(max)>0)errors.add(v("minPrice","must not exceed maxPrice"));var attrs=new LinkedHashMap<String,List<UUID>>();if(attribute!=null){if(attribute.size()>50)errors.add(v("attribute","at most 50 entries are allowed"));for(String raw:attribute){int c=raw.indexOf(':');if(c<1||c==raw.length()-1){errors.add(v("attribute","must use code:valueId"));continue;}try{attrs.computeIfAbsent(raw.substring(0,c),x->new ArrayList<>()).add(UUID.fromString(raw.substring(c+1)));}catch(IllegalArgumentException e){errors.add(v("attribute","valueId must be a UUID"));}}if(attrs.size()>10)errors.add(v("attribute","at most 10 attribute codes are allowed"));attrs.forEach((k,vs)->{if(vs.size()>50)errors.add(v("attribute","at most 50 values per code are allowed"));});}if(!errors.isEmpty())throw new InvalidCatalogQueryException(errors);return reads.browse(new CatalogQuery(page,size,sort,cats,attrs,availability,min,max,currency));}
 @GetMapping("/by-slug/{slug}") ProductDetail bySlug(@PathVariable String slug){if(slug.length()>180||!SLUG.matcher(slug).matches())throw new MalformedCatalogRequestException();return reads.findBySlug(slug).orElseThrow(ProductNotFoundException::new);}@GetMapping("/{productId}") ProductDetail byId(@PathVariable UUID productId){return reads.findById(productId).orElseThrow(ProductNotFoundException::new);}
 private static InvalidCatalogQueryException.Violation v(String f,String m){return new InvalidCatalogQueryException.Violation(f,m);}private static BigDecimal decimal(String f,String raw,List<InvalidCatalogQueryException.Violation> e){if(raw==null)return null;try{var n=new BigDecimal(raw);if(n.scale()>2||n.signum()<0||n.compareTo(new BigDecimal("99999999999999999.99"))>0)throw new ArithmeticException();return n;}catch(RuntimeException x){e.add(v(f,"must be a nonnegative decimal with at most two fractional digits"));return null;}}static final class MalformedCatalogRequestException extends RuntimeException{}
}
